(function() {
  // rucRak Crew Chief (Daryl) widget loader — injects everything needed into
  // the page it's included on. Hosted on Vercel so updating the widget never
  // requires touching the Shopify theme again after this loader is in place.

  // Fonts
  var preconnect = document.createElement('link');
  preconnect.rel = 'preconnect';
  preconnect.href = 'https://fonts.googleapis.com';
  document.head.appendChild(preconnect);

  var fontLink = document.createElement('link');
  fontLink.rel = 'stylesheet';
  fontLink.href = 'https://fonts.googleapis.com/css2?family=Bebas+Neue&family=Oswald:wght@400;500;600;700&family=Inter:wght@400;500;600&family=JetBrains+Mono:wght@400;500;700&display=swap';
  document.head.appendChild(fontLink);

  // Widget CSS
  var styleEl = document.createElement('style');
  styleEl.textContent = "\n  :root{\n    --gunmetal:#1D2024;\n    --panel:#262A30;\n    --panel-raised:#2E333A;\n    --chalk:#F2F0E9;\n    --chalk-dim:#B9B6AC;\n    --orange:#FF6A13;\n    --orange-dim:#7A3A16;\n    --amber:#E8A100;\n    --rivet:#565B64;\n    --rivet-dark:#3A3E45;\n    --good-green:#4C9A5D;\n  }\n  *{box-sizing:border-box;}\n  html,body{margin:0;padding:0;background:transparent;}\n  body{\n    font-family:'Inter',sans-serif;\n    color:var(--chalk);\n  }\n\n  /* ---------- Corner widget shell ---------- */\n  .chat-widget{\n    position:fixed;\n    bottom:20px;\n    right:20px;\n    z-index:1000;\n    display:flex;\n    flex-direction:column;\n    align-items:flex-end;\n  }\n\n  .chat-backdrop{\n    display:none;\n    position:fixed;\n    inset:0;\n    background:rgba(10,11,13,0.6);\n    backdrop-filter:blur(2px);\n    z-index:999;\n  }\n  .chat-backdrop.show{ display:block; }\n\n  /* Desktop: once opened, Daryl takes over as a large centered panel with\n     a dimmed backdrop behind it \u2014 a proper dedicated landing experience\n     instead of a small corner popup. (Mobile has its own true full-screen\n     takeover further down, in the max-width:480px block \u2014 this rule is\n     specifically the desktop/tablet version.) */\n  @media (min-width:481px){\n    .chat-widget.open{\n      top:0; left:0; right:0; bottom:0;\n      width:100vw;\n      align-items:center;\n      justify-content:center;\n    }\n    .chat-widget.open .chat-panel{\n      width:min(760px, 90vw);\n      height:min(760px, 88vh);\n      max-width:none;\n      margin-bottom:0;\n    }\n  }\n\n  .chat-toggle{\n    width:78px;\n    height:172px;\n    border:none;\n    background:transparent;\n    cursor:pointer;\n    position:relative;\n    flex:0 0 auto;\n    padding:0;\n  }\n  .chat-toggle img{\n    display:block;\n    width:100%;\n    height:100%;\n    object-fit:contain;\n    object-position:bottom;\n    filter:drop-shadow(0 8px 16px rgba(0,0,0,0.45));\n  }\n  .chat-toggle:hover img{ transform:scale(1.04); }\n  .chat-toggle .bubble-cta{\n    position:absolute;\n    top:-40px;\n    left:-20px;\n    width:118px;\n    background:var(--orange);\n    color:var(--gunmetal);\n    font-family:'Inter',sans-serif;\n    font-weight:600;\n    font-size:11.5px;\n    line-height:1.25;\n    text-align:center;\n    padding:7px 10px;\n    border-radius:12px 12px 12px 3px;\n    white-space:normal;\n    box-shadow:0 4px 10px rgba(0,0,0,0.35);\n    animation:cta-bob 2.4s ease-in-out infinite;\n  }\n  @keyframes cta-bob{\n    0%,100%{ transform:translateY(0); }\n    50%{ transform:translateY(-4px); }\n  }\n  .chat-toggle .ping{\n    position:absolute;\n    top:36px; right:8px;\n    width:13px; height:13px;\n    border-radius:50%;\n    background:var(--good-green);\n    border:2px solid var(--gunmetal);\n  }\n  .chat-widget.open .chat-toggle{ display:none; }\n\n  .chat-panel{\n    display:none;\n    position:relative;\n    width:380px;\n    max-width:calc(100vw - 24px);\n    height:min(640px, calc(100vh - 100px));\n    margin-bottom:12px;\n  }\n  .chat-widget.open .chat-panel{ display:flex; flex-direction:column; }\n\n  .crew-chief-card{\n    position:absolute;\n    bottom:0;\n    left:-190px; /* his right side overlaps ~30px into the panel \u2014 actually touching now the image has no dead padding */\n    width:220px; /* larger, and no longer wasted on invisible transparent margins */\n    z-index:2;\n    pointer-events:none;\n  }\n  .crew-chief-card img{\n    display:block;\n    width:100%;\n    filter:drop-shadow(0 10px 14px rgba(0,0,0,0.45));\n  }\n  .crew-chief-card .cc-caption{\n    position:absolute;\n    bottom:6px;\n    left:50%;\n    transform:translateX(-50%);\n    font-family:'JetBrains Mono',monospace;\n    font-size:8px;\n    color:var(--chalk);\n    background:rgba(29,32,36,0.75);\n    border:0.5px solid var(--rivet-dark);\n    padding:2px 7px;\n    border-radius:3px;\n    text-align:center;\n    letter-spacing:0.02em;\n    white-space:nowrap;\n  }\n  @media (max-width:620px){\n    .crew-chief-card{ display:none; }\n  }\n  @media (max-width:480px){\n    /* On a phone, a small floating box in the corner just doesn't work \u2014\n       there's no room to spare. Go full-screen instead, the way basically\n       every real mobile chat/support experience does (Intercom, Zendesk,\n       etc.) \u2014 maximize the actual conversation space rather than fighting\n       to fit a desktop-shaped widget into a small screen.\n       (Simple-selector overrides like .plate, .brand, .chat-panel-close etc.\n       live in the LATER mobile media query near the end of this stylesheet,\n       not here \u2014 CSS cascade order matters for same-specificity rules, and\n       those base styles are defined further down than this block.) */\n    .chat-widget.open{\n      top:0; left:0; right:0; bottom:0;\n      width:100vw;\n      align-items:stretch;\n    }\n    .chat-widget.open .chat-panel{\n      display:flex;\n      width:100vw;\n      max-width:none;\n      height:100dvh;\n      height:100vh; /* fallback for browsers without dvh support */\n      margin-bottom:0;\n    }\n    .chat-widget.open .app{\n      border-radius:0;\n      box-shadow:none;\n      height:100%;\n    }\n    .chat-widget.open .crew-chief-card{ display:none; } /* already hidden below 620px, kept explicit here too */\n  }\n\n  .chat-panel-close{\n    position:absolute;\n    top:10px; right:10px;\n    z-index:3;\n    width:26px; height:26px;\n    border-radius:50%;\n    border:0.5px solid var(--rivet-dark);\n    background:var(--panel-raised);\n    color:var(--chalk-dim);\n    cursor:pointer;\n    font-size:14px;\n    line-height:1;\n    display:flex;\n    align-items:center;\n    justify-content:center;\n  }\n  .chat-panel-close:hover{ color:var(--chalk); border-color:var(--orange); }\n\n  .chat-home-link{\n    position:absolute;\n    top:14px; left:14px;\n    z-index:3;\n    font-family:'Inter',sans-serif;\n    font-size:12px;\n    font-weight:500;\n    color:var(--chalk-dim);\n    text-decoration:none;\n    background:rgba(0,0,0,0.25);\n    padding:5px 10px;\n    border-radius:12px;\n  }\n  .chat-home-link:hover{ color:var(--chalk); }\n\n  .app{\n    width:100%;\n    max-width:none;\n    height:100%;\n    display:flex;\n    flex-direction:column;\n    overflow:hidden;\n    border-radius:12px;\n    box-shadow:0 16px 40px rgba(0,0,0,0.45);\n    background:\n      linear-gradient(180deg, rgba(255,255,255,0.02), rgba(255,255,255,0) 120px),\n      var(--gunmetal);\n  }\n\n  /* ---------- Spec-plate header ---------- */\n  .plate{\n    position:relative;\n    margin:14px 14px 0 14px;\n    padding:18px 20px 16px 20px;\n    background:linear-gradient(155deg,#33383F,#23262B 70%);\n    border:1px solid var(--rivet-dark);\n    border-radius:16px;\n    box-shadow:0 1px 0 rgba(255,255,255,0.04) inset, 0 8px 18px rgba(0,0,0,0.28);\n  }\n  /* Rivets removed \u2014 literal screw-head details were reading as too\n     industrial/hardware-store for a customer-facing entry point. */\n\n  .plate-top{display:flex;align-items:baseline;justify-content:space-between;gap:10px;flex-wrap:wrap;}\n  .brand{\n    font-family:'Bebas Neue',sans-serif;\n    font-size:32px;\n    letter-spacing:1px;\n    color:var(--chalk);\n    line-height:1;\n  }\n  .brand span{color:var(--orange);}\n  .plate-badge{\n    font-family:'Inter',sans-serif;\n    font-size:11px;\n    color:var(--gunmetal);\n    background:var(--amber);\n    padding:5px 11px;\n    border-radius:12px;\n    font-weight:600;\n    white-space:nowrap;\n  }\n  .plate-sub{\n    font-family:'Inter',sans-serif;\n    font-size:12.5px;\n    color:var(--chalk-dim);\n    margin-top:6px;\n  }\n\n  /* ---------- torque gauge (signature element) ---------- */\n  .gauge-row{\n    display:flex;\n    align-items:center;\n    gap:10px;\n    margin-top:12px;\n    padding-top:12px;\n    border-top:1px solid var(--rivet-dark);\n  }\n  .gauge{width:34px;height:34px;flex:0 0 auto;}\n  .gauge-needle{\n    transform-origin:17px 17px;\n    transform:rotate(-55deg);\n    transition:transform 0.4s cubic-bezier(.34,1.56,.64,1);\n  }\n  .gauge-label{\n    font-family:'Inter',sans-serif;\n    font-size:12px;\n    color:var(--chalk-dim);\n  }\n  .gauge-label b{color:var(--good-green);font-weight:700;}\n  .gauge.thinking .gauge-needle{\n    animation:tick 0.9s ease-in-out infinite;\n  }\n  @keyframes tick{\n    0%{transform:rotate(-55deg);}\n    50%{transform:rotate(55deg);}\n    100%{transform:rotate(-55deg);}\n  }\n\n  /* ---------- ticket / chat log ---------- */\n  .ticket{\n    flex:1;\n    margin:14px 14px 0 14px;\n    background:var(--panel);\n    border:1px solid var(--rivet-dark);\n    border-radius:6px 6px 0 0;\n    border-bottom:none;\n    position:relative;\n    display:flex;\n    flex-direction:column;\n    min-height:0;\n  }\n  .ticket::before{\n    content:\"\";\n    position:absolute;\n    top:-1px;left:16px;right:16px;\n    height:0;\n    border-top:2px dashed var(--rivet);\n    opacity:0.35;\n  }\n  .log{\n    flex:1;\n    overflow-y:auto;\n    padding:20px 16px 10px 16px;\n    display:flex;\n    flex-direction:column;\n    gap:14px;\n    min-height:220px;\n    max-height:52vh;\n  }\n  .msg{\n    max-width:88%;\n    padding:11px 13px;\n    border-radius:8px;\n    font-size:14.5px;\n    line-height:1.5;\n    white-space:pre-wrap;\n  }\n  .msg-link{\n    color:var(--orange);\n    text-decoration:underline;\n    word-break:break-all;\n  }\n  .msg-link:hover{ color:var(--chalk); }\n  .msg.user{\n    align-self:flex-end;\n    background:var(--orange-dim);\n    border:1px solid rgba(255,106,19,0.35);\n    color:var(--chalk);\n    border-bottom-right-radius:2px;\n  }\n  .msg.bot{\n    align-self:flex-start;\n    background:var(--panel-raised);\n    border:1px solid var(--rivet-dark);\n    color:var(--chalk);\n    border-bottom-left-radius:2px;\n  }\n  .msg.bot b{color:var(--orange);}\n  .msg .tag{\n    display:block;\n    font-family:'JetBrains Mono',monospace;\n    font-size:9.5px;\n    letter-spacing:0.6px;\n    text-transform:uppercase;\n    color:var(--chalk-dim);\n    margin-bottom:5px;\n    opacity:0.75;\n  }\n  .msg.bot .tag{color:var(--orange);}\n  .typing{display:flex;gap:4px;align-items:center;padding:4px 0;}\n  .typing span{\n    width:5px;height:5px;border-radius:50%;\n    background:var(--chalk-dim);\n    animation:blink 1.1s infinite ease-in-out;\n  }\n  .typing span:nth-child(2){animation-delay:0.15s;}\n  .typing span:nth-child(3){animation-delay:0.3s;}\n  @keyframes blink{0%,80%,100%{opacity:0.25;}40%{opacity:1;}}\n\n  /* ---------- quick chips ---------- */\n  .chips{\n    display:flex;\n    flex-wrap:wrap;\n    gap:8px;\n    padding:12px 14px;\n    background:var(--panel);\n    border-left:1px solid var(--rivet-dark);\n    border-right:1px solid var(--rivet-dark);\n  }\n  .chip{\n    flex:0 0 auto;\n    max-width:100%;\n    font-family:'Inter',sans-serif;\n    font-size:12.5px;\n    line-height:1.3;\n    color:var(--chalk-dim);\n    background:var(--panel-raised);\n    border:1px solid transparent;\n    padding:8px 13px;\n    border-radius:14px;\n    cursor:pointer;\n    white-space:normal;\n    transition:border-color 0.15s ease, color 0.15s ease;\n  }\n  .chip:hover{border-color:var(--orange);color:var(--chalk);}\n\n  /* ---------- input keypad ---------- */\n  .keypad-wrap{\n    margin:0 14px 14px 14px;\n  }\n  .attach-preview{\n    display:none;\n    align-items:center;\n    gap:10px;\n    background:var(--panel-raised);\n    border:1px solid var(--rivet-dark);\n    border-bottom:none;\n    border-radius:6px 6px 0 0;\n    padding:10px 12px;\n  }\n  .attach-preview.show{display:flex;}\n  .attach-thumbs{\n    display:flex;\n    gap:8px;\n    overflow-x:auto;\n    flex:0 1 auto;\n  }\n  .attach-thumb{\n    position:relative;\n    flex:0 0 auto;\n    width:48px;height:48px;\n  }\n  .attach-thumb img{\n    width:48px;height:48px;\n    object-fit:cover;\n    border-radius:4px;\n    border:1px solid var(--rivet-dark);\n    display:block;\n  }\n  .attach-thumb .thumb-remove{\n    position:absolute;\n    top:-6px;right:-6px;\n    width:18px;height:18px;\n    border-radius:50%;\n    background:var(--gunmetal);\n    border:1px solid var(--rivet-dark);\n    color:var(--chalk-dim);\n    font-size:11px;\n    line-height:1;\n    display:flex;\n    align-items:center;\n    justify-content:center;\n    cursor:pointer;\n    padding:0;\n  }\n  .attach-thumb .thumb-remove:hover{color:var(--chalk);border-color:var(--orange);}\n  .attach-preview .attach-label{\n    flex:1;\n    font-family:'JetBrains Mono',monospace;\n    font-size:11px;\n    color:var(--chalk-dim);\n    white-space:nowrap;\n  }\n  .attach-preview button:not(.thumb-remove){\n    background:none;\n    border:1px solid var(--rivet-dark);\n    color:var(--chalk-dim);\n    border-radius:4px;\n    font-size:11px;\n    padding:5px 9px;\n    cursor:pointer;\n    font-family:'JetBrains Mono',monospace;\n    flex:0 0 auto;\n  }\n  .attach-preview button:not(.thumb-remove):hover{color:var(--chalk);border-color:var(--orange);}\n  .keypad{\n    background:var(--panel-raised);\n    border:1px solid var(--rivet-dark);\n    border-radius:0 0 6px 6px;\n    padding:12px;\n    display:flex;\n    gap:8px;\n    align-items:flex-end;\n  }\n  button.attach{\n    flex:0 0 auto;\n    background:var(--gunmetal);\n    border:1px solid var(--rivet-dark);\n    color:var(--chalk-dim);\n    border-radius:5px;\n    padding:10px 12px;\n    cursor:pointer;\n    font-size:17px;\n    line-height:1;\n    transition:border-color 0.15s, color 0.15s;\n  }\n  button.attach:hover{border-color:var(--orange);color:var(--chalk);}\n  button.attach:disabled{opacity:0.4;cursor:not-allowed;}\n  .attach-menu-wrap{position:relative;flex:0 0 auto;}\n  .attach-menu{\n    display:none;\n    position:absolute;\n    bottom:calc(100% + 8px);\n    left:0;\n    flex-direction:column;\n    gap:4px;\n    background:var(--panel-raised);\n    border:1px solid var(--rivet-dark);\n    border-radius:6px;\n    padding:6px;\n    box-shadow:0 8px 18px rgba(0,0,0,0.4);\n    z-index:20;\n    min-width:190px;\n  }\n  .attach-menu.show{display:flex;}\n  .attach-menu button{\n    background:none;\n    border:none;\n    color:var(--chalk);\n    text-align:left;\n    padding:9px 10px;\n    border-radius:4px;\n    cursor:pointer;\n    font-family:'Inter',sans-serif;\n    font-size:13.5px;\n    white-space:nowrap;\n  }\n  .attach-menu button:hover{background:var(--gunmetal);color:var(--orange);}\n  .msg img.attached{\n    display:block;\n    max-width:220px;\n    border-radius:6px;\n    margin-bottom:6px;\n    border:1px solid var(--rivet-dark);\n  }\n  textarea{\n    flex:1;\n    resize:none;\n    background:var(--gunmetal);\n    border:1px solid var(--rivet-dark);\n    border-radius:5px;\n    color:var(--chalk);\n    font-family:'Inter',sans-serif;\n    font-size:14.5px;\n    padding:10px 12px;\n    min-height:22px;\n    max-height:120px;\n    line-height:1.4;\n  }\n  textarea:focus{outline:none;border-color:var(--orange);}\n  textarea::placeholder{color:var(--chalk-dim);}\n  button.send{\n    font-family:'Oswald',sans-serif;\n    font-weight:600;\n    letter-spacing:0.5px;\n    text-transform:uppercase;\n    font-size:12.5px;\n    background:var(--orange);\n    color:#241000;\n    border:none;\n    border-radius:5px;\n    padding:12px 16px;\n    cursor:pointer;\n    transition:filter 0.15s;\n    flex:0 0 auto;\n  }\n  button.send:hover{filter:brightness(1.08);}\n  button.send:disabled{opacity:0.5;cursor:not-allowed;}\n\n  .footnote{\n    text-align:center;\n    font-family:'JetBrains Mono',monospace;\n    font-size:10px;\n    color:var(--rivet);\n    letter-spacing:0.3px;\n    padding:0 20px 18px 20px;\n  }\n\n  /* ---------- Voice mode ---------- */\n  .mode-select-view{\n    display:none;\n    flex:1;\n    flex-direction:column;\n    align-items:center;\n    justify-content:center;\n    gap:14px;\n    padding:20px;\n    text-align:center;\n    overflow-y:auto; /* safety net \u2014 shouldn't be needed if the content above fits, but never invisible/cut off if it doesn't */\n    min-height:0;\n  }\n  .mode-select-heading{\n    font-family:'Inter',sans-serif;\n    font-size:18px;\n    font-weight:600;\n    color:var(--chalk);\n  }\n  .mode-select-channels{\n    display:flex;\n    gap:12px;\n  }\n  .mode-channel-btn{\n    display:flex;\n    flex-direction:column;\n    align-items:center;\n    gap:4px;\n    background:linear-gradient(180deg, var(--orange), #E85A0A);\n    border:none;\n    color:#fff;\n    border-radius:18px;\n    padding:14px 32px;\n    cursor:pointer;\n    font-family:'Inter',sans-serif;\n    font-size:14px;\n    font-weight:600;\n    box-shadow:0 4px 14px rgba(255,106,19,0.32);\n    transition:transform 0.15s ease, box-shadow 0.15s ease;\n  }\n  .mode-channel-btn:hover{ transform:translateY(-1px); box-shadow:0 6px 18px rgba(255,106,19,0.42); }\n  .mode-channel-icon{ font-size:22px; }\n\n  .mode-select-or{\n    font-family:'Inter',sans-serif;\n    font-size:12px;\n    color:var(--chalk-dim);\n  }\n\n  .mode-select-chips{\n    display:flex;\n    flex-direction:column;\n    gap:8px;\n    width:100%;\n    max-width:300px;\n  }\n  .mode-select-chips .chip{\n    cursor:pointer;\n    background:var(--panel-raised);\n    border:1px solid transparent;\n    color:var(--chalk);\n    font-family:'Inter',sans-serif;\n    font-size:13px;\n    line-height:1.35;\n    padding:12px 16px;\n    border-radius:14px;\n    text-align:left;\n    transition:background 0.15s ease, border-color 0.15s ease;\n  }\n  .mode-select-chips .chip:hover{ border-color:var(--orange); background:#343A42; }\n\n  .text-mode-view{\n    display:none;\n    flex-direction:column;\n    flex:1;\n    min-height:0;\n  }\n  /* Vapi's html-script-tag loader injects its own floating call button \u2014\n     we have our own custom Talk button and voice UI, so hide theirs entirely. */\n  .vapi-btn{ display:none !important; }\n\n  .voice-mode-view{\n    display:none;\n    flex:1;\n    flex-direction:column;\n    align-items:center;\n    justify-content:center;\n    gap:14px;\n    padding:24px;\n    text-align:center;\n  }\n  .app[data-mode=\"select\"] .mode-select-view{ display:flex; }\n  .app[data-mode=\"text\"] .text-mode-view{ display:flex; }\n  .app[data-mode=\"voice\"] .voice-mode-view{ display:flex; }\n\n  .voice-status{\n    font-family:'JetBrains Mono',monospace;\n    font-size:12px;\n    letter-spacing:0.05em;\n    color:var(--chalk-dim);\n    text-transform:uppercase;\n  }\n  .voice-orb-btn{\n    background:none;\n    border:none;\n    cursor:pointer;\n    padding:0;\n    display:flex;\n    flex-direction:column;\n    align-items:center;\n    gap:10px;\n  }\n  .voice-orb-btn:hover .voice-orb{ transform:scale(1.04); }\n  .voice-orb-label{\n    font-family:'Inter',sans-serif;\n    font-size:13px;\n    font-weight:500;\n    color:var(--orange);\n  }\n  .voice-orb{\n    width:96px; height:96px;\n    border-radius:50%;\n    background:radial-gradient(circle at 35% 30%, var(--orange), var(--orange-dim));\n    box-shadow:0 0 0 0 rgba(255,106,19,0.45);\n  }\n  .voice-orb.idle{ animation:voice-idle-pulse 2.4s ease-in-out infinite; }\n  .voice-orb.listening{ animation:voice-pulse 1.6s ease-in-out infinite; }\n  .voice-orb.speaking{ animation:voice-pulse 0.5s ease-in-out infinite; }\n  @keyframes voice-pulse{\n    0%{ box-shadow:0 0 0 0 rgba(255,106,19,0.45); }\n    70%{ box-shadow:0 0 0 22px rgba(255,106,19,0); }\n    100%{ box-shadow:0 0 0 0 rgba(255,106,19,0); }\n  }\n  @keyframes voice-idle-pulse{\n    0%{ box-shadow:0 0 0 0 rgba(255,106,19,0.3); }\n    50%{ box-shadow:0 0 0 12px rgba(255,106,19,0); }\n    100%{ box-shadow:0 0 0 0 rgba(255,106,19,0); }\n  }\n  .voice-sub{\n    font-size:13.5px;\n    color:var(--chalk-dim);\n    max-width:280px;\n  }\n  .voice-actions{\n    display:flex;\n    gap:10px;\n    margin-top:8px;\n  }\n  .voice-actions button{\n    font-family:'Inter',sans-serif;\n    font-size:12.5px;\n    font-weight:500;\n    padding:9px 14px;\n    border-radius:6px;\n    cursor:pointer;\n  }\n  .voice-end{\n    background:var(--orange);\n    color:var(--gunmetal);\n    border:none;\n  }\n  .voice-back-text{\n    background:none;\n    color:var(--chalk-dim);\n    border:1px solid var(--rivet-dark);\n    font-family:'Inter',sans-serif;\n    font-size:12.5px;\n    font-weight:500;\n    padding:9px 14px;\n    border-radius:6px;\n    cursor:pointer;\n    margin-top:4px;\n  }\n  .voice-back-text:hover{ color:var(--chalk); border-color:var(--orange); }\n\n  .voice-photo-menu-wrap{ position:relative; }\n  .voice-photo-btn{\n    font-family:'Inter',sans-serif;\n    font-size:12.5px;\n    font-weight:500;\n    padding:9px 14px;\n    border-radius:6px;\n    cursor:pointer;\n    background:none;\n    color:var(--chalk-dim);\n    border:1px solid var(--rivet-dark);\n  }\n  .voice-photo-btn:hover{ color:var(--chalk); border-color:var(--orange); }\n  .voice-photo-status{\n    min-height:16px;\n    font-size:12px;\n    color:var(--chalk-dim);\n    font-family:'JetBrains Mono',monospace;\n  }\n  .voice-photo-status.working{ color:var(--amber); }\n  .voice-photo-status.done{ color:var(--good-green); }\n  .voice-photo-status.error{ color:#E24B4A; }\n\n  ::-webkit-scrollbar{width:8px;}\n  ::-webkit-scrollbar-thumb{background:var(--rivet-dark);border-radius:4px;}\n\n  @media (max-width:480px){\n    .msg{max-width:94%;}\n\n    /* Compact top-bar header instead of the desktop spec-plate treatment \u2014\n       one slim row, not a whole decorative card. This has to live in THIS\n       later media query block (not the earlier one near the top of the\n       stylesheet) because these are same-specificity overrides of .plate,\n       .brand, etc. \u2014 CSS cascade resolves ties by source order, so this\n       needs to come after those base rules are defined. */\n    .plate{\n      margin:0;\n      padding:14px 52px 14px 16px; /* right padding clears the close button */\n      padding-top:calc(14px + env(safe-area-inset-top, 0px));\n      background:var(--gunmetal);\n      border:none;\n      border-radius:0;\n      box-shadow:0 1px 0 var(--rivet-dark);\n    }\n    .plate-top{ align-items:center; }\n    .brand{ font-size:19px; }\n    .plate-badge{ font-size:8.5px; padding:3px 6px; }\n    .plate-sub{ display:none; }\n    .gauge-row{ display:none; }\n\n    .chat-panel-close{\n      top:calc(10px + env(safe-area-inset-top, 0px));\n      right:12px;\n      width:32px; height:32px;\n      font-size:16px;\n    }\n\n    /* A bit more breathing room now that there's a full screen to work\n       with instead of a cramped floating box. */\n    .keypad-wrap{ padding-bottom:env(safe-area-inset-bottom, 0px); }\n  }\n\n  @media (prefers-reduced-motion: reduce){\n    .gauge-needle, .typing span{animation:none !important;transition:none !important;}\n  }\n";
  document.head.appendChild(styleEl);

  // Widget HTML
  var container = document.createElement('div');
  container.innerHTML = "\n<div class=\"chat-backdrop\" id=\"chatBackdrop\"></div>\n<div class=\"chat-widget\" id=\"chatWidget\">\n\n  <div class=\"chat-panel\">\n    <div class=\"crew-chief-card\">\n      <img src=\"https://rucrak-crew-chief.vercel.app/crew-chief.png\" alt=\"Daryl, rucRak's Crew Chief\">\n      <div class=\"cc-caption\">DARYL \u00b7 ON DUTY</div>\n    </div>\n    <a class=\"chat-home-link\" href=\"https://rucrak.com/\" target=\"_blank\" rel=\"noopener noreferrer\" title=\"Back to rucrak.com\">\u2190 rucrak.com</a>\n    <button class=\"chat-panel-close\" id=\"chatPanelClose\" type=\"button\" title=\"Close chat\" aria-label=\"Close chat\">&times;</button>\n<div class=\"app\">\n\n  <div class=\"plate\">\n    <div class=\"plate-top\">\n      <div class=\"brand\">RUC<span>RAK</span> FIELD SUPPORT</div>\n      <div class=\"plate-badge\">DARYL \u00b7 ON DUTY</div>\n    </div>\n    <div class=\"plate-sub\">Installation \u00b7 Fitment \u00b7 Troubleshooting \u2014 GRUNT / GUNNY / SERGEANT</div>\n\n    <div class=\"gauge-row\">\n      <svg class=\"gauge\" id=\"gauge\" viewBox=\"0 0 34 34\">\n        <path d=\"M4 24 A15 15 0 1 1 30 24\" fill=\"none\" stroke=\"#3A3E45\" stroke-width=\"3\" stroke-linecap=\"round\"/>\n        <path d=\"M11 27 A9 9 0 1 1 23 27\" fill=\"none\" stroke=\"#4C9A5D\" stroke-width=\"3\" stroke-linecap=\"round\" opacity=\"0.55\"/>\n        <g class=\"gauge-needle\" id=\"needle\">\n          <line x1=\"17\" y1=\"17\" x2=\"17\" y2=\"6\" stroke=\"#FF6A13\" stroke-width=\"2\" stroke-linecap=\"round\"/>\n          <circle cx=\"17\" cy=\"17\" r=\"2.2\" fill=\"#F2F0E9\"/>\n        </g>\n      </svg>\n      <div class=\"gauge-label\" id=\"gaugeLabel\">Torque check: <b>GOOD &amp; SNUG</b> \u2014 ask away, crew chief's ready.</div>\n    </div>\n  </div>\n\n  <div class=\"mode-select-view\" id=\"modeSelectView\">\n    <div class=\"mode-select-heading\">What do you need help with?</div>\n    <div class=\"mode-select-channels\">\n      <button class=\"mode-channel-btn\" id=\"modeChooseTextBtn\" type=\"button\">\n        <span class=\"mode-channel-icon\">\ud83d\udcac</span>\n        <span>Type</span>\n      </button>\n      <button class=\"mode-channel-btn\" id=\"modeChooseVoiceBtn\" type=\"button\">\n        <span class=\"mode-channel-icon\">\ud83c\udf99\ufe0f</span>\n        <span>Talk</span>\n      </button>\n    </div>\n    <div class=\"mode-select-or\">or tap a question below</div>\n    <div class=\"mode-select-chips\" id=\"modeSelectChips\"></div>\n  </div>\n\n  <div class=\"text-mode-view\" id=\"textModeView\">\n    <div class=\"ticket\">\n      <div class=\"log\" id=\"log\"></div>\n    </div>\n    <div class=\"chips\" id=\"chips\"></div>\n\n    <div class=\"keypad-wrap\">\n      <div class=\"attach-preview\" id=\"attachPreview\">\n        <div class=\"attach-thumbs\" id=\"attachThumbs\"></div>\n        <span class=\"attach-label\" id=\"attachLabel\">Photos attached \u2014 send with your message</span>\n        <button id=\"attachRemove\" type=\"button\">Clear all</button>\n      </div>\n      <div class=\"keypad\">\n        <input type=\"file\" id=\"fileInputCamera\" accept=\"image/*\" capture=\"environment\" style=\"display:none\">\n        <input type=\"file\" id=\"fileInputGallery\" accept=\"image/*\" multiple style=\"display:none\">\n        <div class=\"attach-menu-wrap\">\n          <button class=\"attach\" id=\"attachBtn\" type=\"button\" title=\"Attach fitment photos\">\ud83d\udcf7</button>\n          <div class=\"attach-menu\" id=\"attachMenu\">\n            <button type=\"button\" id=\"attachMenuCamera\">\ud83d\udcf7 Take Photo</button>\n            <button type=\"button\" id=\"attachMenuGallery\">\ud83d\uddbc\ufe0f Choose from Library</button>\n          </div>\n        </div>\n        <textarea id=\"input\" rows=\"1\" placeholder=\"Type your question...\"></textarea>\n        <button class=\"attach\" id=\"talkBtn\" type=\"button\" title=\"Talk to Daryl\">\ud83c\udf99\ufe0f</button>\n        <button class=\"send\" id=\"sendBtn\">Send</button>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"voice-mode-view\" id=\"voiceModeView\">\n    <div class=\"voice-status\" id=\"voiceStatus\">Ready when you are</div>\n    <button class=\"voice-orb-btn\" id=\"voiceStartBtn\" type=\"button\">\n      <span class=\"voice-orb\" id=\"voiceOrb\"></span>\n      <span class=\"voice-orb-label\">Tap to start talking</span>\n    </button>\n    <div class=\"voice-sub\" id=\"voiceSub\">Crew Chief will start talking as soon as you tap in.</div>\n\n    <input type=\"file\" id=\"voiceFileInputCamera\" accept=\"image/*\" capture=\"environment\" style=\"display:none\">\n    <input type=\"file\" id=\"voiceFileInputGallery\" accept=\"image/*\" style=\"display:none\">\n    <div class=\"voice-photo-menu-wrap\">\n      <button class=\"voice-photo-btn\" id=\"voicePhotoBtn\" type=\"button\" title=\"Send a fitment photo\">\ud83d\udcf7 Send a photo</button>\n      <div class=\"attach-menu\" id=\"voicePhotoMenu\">\n        <button type=\"button\" id=\"voicePhotoMenuCamera\">\ud83d\udcf7 Take Photo</button>\n        <button type=\"button\" id=\"voicePhotoMenuGallery\">\ud83d\uddbc\ufe0f Choose from Library</button>\n      </div>\n    </div>\n    <div class=\"voice-photo-status\" id=\"voicePhotoStatus\"></div>\n\n    <div class=\"voice-actions\" id=\"voiceActiveActions\" style=\"display:none;\">\n      <button class=\"voice-end\" id=\"voiceEndBtn\" type=\"button\">End call</button>\n    </div>\n    <button class=\"voice-back-text\" id=\"voiceBackTextBtn\" type=\"button\">Switch to typing</button>\n  </div>\n\n  <div class=\"footnote\">Answers are grounded in rucRak documentation &amp; verified install transcripts. Safety-critical or undocumented items get flagged, not guessed.</div>\n</div>\n  </div>\n\n  <button class=\"chat-toggle\" id=\"chatToggle\" type=\"button\" title=\"Chat with Daryl\" aria-label=\"Open chat\">\n    <span class=\"bubble-cta\">Questions? Daryl's On Duty.</span>\n    <img src=\"https://rucrak-crew-chief.vercel.app/crew-chief.png\" alt=\"Crew Chief\">\n    <span class=\"ping\"></span>\n  </button>\n\n</div>\n\n\n";
  document.body.appendChild(container);

  // Widget JS — runs after the HTML above is in the DOM, since this script
  // itself executes synchronously right after container is appended.
  var widgetScript = document.createElement('script');
  widgetScript.textContent = "\n// System prompt now lives server-side in api/chat.js \u2014 never expose it or your API key in the browser.\nconst CHAT_ENDPOINT = 'https://rucrak-crew-chief.vercel.app/api/chat'; // change to your deployed API URL if hosted separately\n\nlet messages = [];\nlet pendingImages = []; // array of { base64, mediaType, previewSrc } \u2014 cleared after send\nconst log = document.getElementById('log');\nconst input = document.getElementById('input');\nconst sendBtn = document.getElementById('sendBtn');\nconst gauge = document.getElementById('gauge');\nconst gaugeLabel = document.getElementById('gaugeLabel');\nconst fileInputCamera = document.getElementById('fileInputCamera');\nconst fileInputGallery = document.getElementById('fileInputGallery');\nconst attachBtn = document.getElementById('attachBtn');\nconst attachMenu = document.getElementById('attachMenu');\nconst attachMenuCamera = document.getElementById('attachMenuCamera');\nconst attachMenuGallery = document.getElementById('attachMenuGallery');\nconst attachPreview = document.getElementById('attachPreview');\nconst attachThumbs = document.getElementById('attachThumbs');\nconst attachLabel = document.getElementById('attachLabel');\nconst attachRemove = document.getElementById('attachRemove');\n\nconst STARTERS = [\n  \"Which RucRak model do I need for my vehicle?\",\n  \"Can I carry E Bikes on this?\",\n  \"Does this block my backup camera?\",\n  \"Can I access my tailgate?\",\n  \"I have an installation question.\",\n  \"Do I need any thing extra to make it fit my vehicle?\"\n];\n\nfunction renderChips(){\n  const chips = document.getElementById('chips');\n  chips.innerHTML = '';\n  STARTERS.forEach(q=>{\n    const c = document.createElement('div');\n    c.className = 'chip';\n    c.textContent = q;\n    c.onclick = ()=>{ input.value = q; sendMessage(); };\n    chips.appendChild(c);\n  });\n}\nrenderChips();\n\n// --- photo attachment: tapping the camera button offers a choice \u2014 Take Photo or Choose\n// from Library \u2014 each routed to its own hidden file input, since relying on a single input\n// to offer both options isn't consistent across browsers/devices. ---\nattachBtn.addEventListener('click', (e)=>{\n  e.stopPropagation();\n  attachMenu.classList.toggle('show');\n});\ndocument.addEventListener('click', ()=> attachMenu.classList.remove('show'));\nattachMenu.addEventListener('click', (e)=> e.stopPropagation());\n\nattachMenuCamera.addEventListener('click', ()=>{\n  attachMenu.classList.remove('show');\n  fileInputCamera.click();\n});\nattachMenuGallery.addEventListener('click', ()=>{\n  attachMenu.classList.remove('show');\n  fileInputGallery.click();\n});\n\n// --- voice-mode photo: same take/choose pattern, but instead of queueing for a text\n// message, the photo goes straight to analysis and gets injected into the live call. ---\nconst voicePhotoBtn = document.getElementById('voicePhotoBtn');\nconst voicePhotoMenu = document.getElementById('voicePhotoMenu');\nconst voicePhotoMenuCamera = document.getElementById('voicePhotoMenuCamera');\nconst voicePhotoMenuGallery = document.getElementById('voicePhotoMenuGallery');\nconst voiceFileInputCamera = document.getElementById('voiceFileInputCamera');\nconst voiceFileInputGallery = document.getElementById('voiceFileInputGallery');\nconst voicePhotoStatus = document.getElementById('voicePhotoStatus');\n\nvoicePhotoBtn.addEventListener('click', (e)=>{\n  e.stopPropagation();\n  voicePhotoMenu.classList.toggle('show');\n});\ndocument.addEventListener('click', ()=> voicePhotoMenu.classList.remove('show'));\nvoicePhotoMenu.addEventListener('click', (e)=> e.stopPropagation());\n\nvoicePhotoMenuCamera.addEventListener('click', ()=>{\n  voicePhotoMenu.classList.remove('show');\n  voiceFileInputCamera.click();\n});\nvoicePhotoMenuGallery.addEventListener('click', ()=>{\n  voicePhotoMenu.classList.remove('show');\n  voiceFileInputGallery.click();\n});\n\nfunction setVoicePhotoStatus(text, kind){\n  voicePhotoStatus.textContent = text;\n  voicePhotoStatus.className = 'voice-photo-status' + (kind ? ' ' + kind : '');\n}\n\n// Lets analyzeVoicePhoto (below) start the call automatically and wait for\n// it to actually connect, rather than just erroring if you tap the photo\n// button before you've tapped \"Tap to start talking\" first.\nlet pendingCallStartResolvers = [];\nfunction waitForVoiceCallActive(){\n  if(voiceCallActive) return Promise.resolve();\n  return new Promise((resolve)=>{\n    pendingCallStartResolvers.push(resolve);\n    startVoiceMode();\n  });\n}\n\nasync function analyzeVoicePhoto(file){\n  if(!voiceCallActive || !vapiInstance){\n    setVoicePhotoStatus('Starting the call first...', 'working');\n    await waitForVoiceCallActive();\n  }\n  setVoicePhotoStatus('Uploading photo...', 'working');\n  let imgData;\n  try {\n    imgData = await compressImageFile(file);\n  } catch(err){\n    setVoicePhotoStatus(err.message || 'Could not read that photo.', 'error');\n    return;\n  }\n\n  setVoicePhotoStatus(\"Crew Chief's looking at it...\", 'working');\n  try {\n    const response = await fetch('https://rucrak-crew-chief.vercel.app/api/analyze-photo', {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({\n        images: [{ media_type: imgData.mediaType, data: imgData.base64 }]\n      })\n    });\n    const data = await response.json();\n    if(!response.ok){\n      throw new Error((data && data.error) || `Server returned ${response.status}`);\n    }\n    const analysisText = (data.text || '').trim();\n    if(!analysisText){\n      throw new Error('Empty analysis returned.');\n    }\n\n    // Inject the analysis into the live call as context \u2014 the assistant on the call\n    // (same Crew Chief persona/voice) will read this and relay it naturally in its\n    // own words on its next turn, without the call ending or restarting.\n    sendVapiMessage(vapiInstance, {\n      role: 'system',\n      content: `The customer just sent a photo during this call. Automated fitment analysis of that photo: ${analysisText}\\n\\nRelay this to the customer naturally in your own voice and style right now \u2014 don't read it verbatim or robotically, explain it like you normally would in conversation.`\n    }, 'photo analysis handoff');\n    setVoicePhotoStatus('Sent \u2014 Crew Chief will bring it up.', 'done');\n    setTimeout(()=> setVoicePhotoStatus('', ''), 4000);\n  } catch(err){\n    console.error('Voice photo analysis failed:', err); // full details in console only\n    setVoicePhotoStatus(\"Couldn't get a read on that photo \u2014 try again in a moment.\", 'error');\n  }\n}\n\nvoiceFileInputCamera.addEventListener('change', (e)=>{\n  const file = e.target.files && e.target.files[0];\n  e.target.value = '';\n  if(file) analyzeVoicePhoto(file);\n});\nvoiceFileInputGallery.addEventListener('change', (e)=>{\n  const file = e.target.files && e.target.files[0];\n  e.target.value = '';\n  if(file) analyzeVoicePhoto(file);\n});\n\nconst MAX_IMAGES = 6; // cap so a big multi-select doesn't blow up the request size\n\nfunction renderAttachThumbs(){\n  attachThumbs.innerHTML = '';\n  pendingImages.forEach((imgData, idx)=>{\n    const thumb = document.createElement('div');\n    thumb.className = 'attach-thumb';\n    const img = document.createElement('img');\n    img.src = imgData.previewSrc;\n    img.alt = 'Attached photo';\n    const removeBtn = document.createElement('button');\n    removeBtn.className = 'thumb-remove';\n    removeBtn.type = 'button';\n    removeBtn.textContent = '\u00d7';\n    removeBtn.title = 'Remove this photo';\n    removeBtn.onclick = ()=>{\n      pendingImages.splice(idx, 1);\n      if(pendingImages.length === 0){\n        attachPreview.classList.remove('show');\n      } else {\n        renderAttachThumbs();\n      }\n    };\n    thumb.appendChild(img);\n    thumb.appendChild(removeBtn);\n    attachThumbs.appendChild(thumb);\n  });\n  attachLabel.textContent = pendingImages.length > 1\n    ? `${pendingImages.length} photos attached \u2014 send with your message`\n    : 'Photo attached \u2014 send with your message';\n}\n\n// Shared by both text-mode attach and voice-mode mid-call photo analysis \u2014\n// shrinks to a reasonable max dimension so uploads stay fast/cheap regardless\n// of how large the original phone photo is. Returns a Promise.\nfunction compressImageFile(file){\n  return new Promise((resolve, reject)=>{\n    if(!file.type.startsWith('image/')){\n      reject(new Error(`\"${file.name}\" doesn't look like a photo.`));\n      return;\n    }\n    const reader = new FileReader();\n    reader.onload = (ev)=>{\n      const img = new Image();\n      img.onload = ()=>{\n        const MAX_DIM = 1200;\n        let w = img.width, h = img.height;\n        if(w > h && w > MAX_DIM){ h = Math.round(h * (MAX_DIM / w)); w = MAX_DIM; }\n        else if(h >= w && h > MAX_DIM){ w = Math.round(w * (MAX_DIM / h)); h = MAX_DIM; }\n        const canvas = document.createElement('canvas');\n        canvas.width = w; canvas.height = h;\n        canvas.getContext('2d').drawImage(img, 0, 0, w, h);\n        const dataUrl = canvas.toDataURL('image/jpeg', 0.82);\n        const base64 = dataUrl.split(',')[1];\n        resolve({ base64, mediaType: 'image/jpeg', previewSrc: dataUrl });\n      };\n      img.onerror = ()=> reject(new Error('Could not read that image file.'));\n      img.src = ev.target.result;\n    };\n    reader.onerror = ()=> reject(new Error('Could not read that file.'));\n    reader.readAsDataURL(file);\n  });\n}\n\nfunction handleSelectedFiles(fileList, inputEl){\n  const files = Array.from(fileList || []);\n  if(!files.length) return;\n\n  const room = MAX_IMAGES - pendingImages.length;\n  if(room <= 0){\n    addMessage('bot', `That's plenty \u2014 I can only look at ${MAX_IMAGES} photos at once. Send what you've got or clear some first.`);\n    inputEl.value = '';\n    return;\n  }\n  const toProcess = files.slice(0, room);\n  if(files.length > room){\n    addMessage('bot', `Grabbing the first ${room} of those \u2014 ${MAX_IMAGES} photos is my limit per message.`);\n  }\n\n  // Sending immediately once photos are picked, rather than leaving them\n  // sitting in a \"pending\" state waiting for a separate Send tap \u2014 that\n  // in-between state looked like nothing had happened. Wait for every\n  // photo in this batch to finish compressing before sending once, not\n  // once per photo.\n  const compressionPromises = toProcess.map(file=>\n    compressImageFile(file)\n      .then((imgData)=>{\n        pendingImages.push(imgData);\n        attachPreview.classList.add('show');\n        renderAttachThumbs();\n        return true;\n      })\n      .catch((err)=>{\n        addMessage('bot', err.message || 'Had trouble reading that photo \u2014 skipping it.');\n        return false;\n      })\n  );\n\n  Promise.all(compressionPromises).then(()=>{\n    if(pendingImages.length > 0){\n      sendMessage();\n    }\n  });\n\n  inputEl.value = ''; // allow re-selecting the same file(s) later\n}\n\nfileInputCamera.addEventListener('change', (e)=>{\n  handleSelectedFiles(e.target.files, fileInputCamera);\n});\nfileInputGallery.addEventListener('change', (e)=>{\n  handleSelectedFiles(e.target.files, fileInputGallery);\n});\n\nattachRemove.addEventListener('click', ()=>{\n  pendingImages = [];\n  attachPreview.classList.remove('show');\n});\n\nfunction escapeHtml(str){\n  return str.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');\n}\nfunction formatBotText(str){\n  let s = escapeHtml(str);\n  s = s.replace(/\\*\\*(.+?)\\*\\*/g, '<b>$1</b>');\n  // Turn plain URLs into actual tappable links \u2014 since Daryl may share\n  // install videos, manual pages, etc., these need to be clickable, not\n  // just plain text the customer has to manually copy.\n  s = s.replace(/(https?:\\/\\/[^\\s<]+)/g, '<a href=\"$1\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"msg-link\">$1</a>');\n  return s;\n}\n\nfunction addMessage(role, text, imagePreviewSrcs){\n  const div = document.createElement('div');\n  div.className = 'msg ' + (role === 'user' ? 'user' : 'bot');\n  const tag = document.createElement('span');\n  tag.className = 'tag';\n  tag.textContent = role === 'user' ? 'You' : 'Crew Chief';\n  div.appendChild(tag);\n  const previews = Array.isArray(imagePreviewSrcs) ? imagePreviewSrcs : (imagePreviewSrcs ? [imagePreviewSrcs] : []);\n  previews.forEach(src=>{\n    const img = document.createElement('img');\n    img.className = 'attached';\n    img.src = src;\n    img.alt = 'Attached photo';\n    div.appendChild(img);\n  });\n  const body = document.createElement('span');\n  if(role === 'user'){\n    body.textContent = text;\n  } else {\n    body.innerHTML = formatBotText(text);\n  }\n  div.appendChild(body);\n  log.appendChild(div);\n  log.scrollTop = log.scrollHeight;\n  return div;\n}\n\nfunction setThinking(on){\n  gauge.classList.toggle('thinking', on);\n  gaugeLabel.innerHTML = on\n    ? 'Torque check: <b style=\"color:var(--amber)\">HOLD YER HORSES...</b>'\n    : 'Torque check: <b>GOOD &amp; SNUG</b> \u2014 ask away, crew chief\\'s ready.';\n}\n\n\nasync function sendMessage(){\n  const text = input.value.trim();\n  const hasImages = pendingImages.length > 0;\n  if(!text && !hasImages) return;\n\n  input.value = '';\n  input.style.height = 'auto';\n  sendBtn.disabled = true;\n\n  // Build the outgoing content: array with image(s) (if any) + text, or just a string.\n  let outgoingContent;\n  if(hasImages){\n    const blocks = pendingImages.map(imgData => ({\n      type: 'image',\n      source: { type: 'base64', media_type: imgData.mediaType, data: imgData.base64 }\n    }));\n    const defaultText = pendingImages.length > 1\n      ? \"Here's a few photos for a fitment check \u2014 can you take a look?\"\n      : \"Here's a photo for a fitment check \u2014 can you take a look?\";\n    blocks.push({ type: 'text', text: text || defaultText });\n    outgoingContent = blocks;\n  } else {\n    outgoingContent = text;\n  }\n\n  const previewSrcs = pendingImages.map(imgData => imgData.previewSrc);\n  addMessage('user', text || (pendingImages.length > 1 ? \"(photos attached)\" : \"(photo attached)\"), hasImages ? previewSrcs : null);\n  messages.push({ role: 'user', content: outgoingContent });\n\n  pendingImages = [];\n  attachPreview.classList.remove('show');\n  attachThumbs.innerHTML = '';\n\n  const typingDiv = document.createElement('div');\n  typingDiv.className = 'msg bot';\n  typingDiv.innerHTML = '<span class=\"tag\">Crew Chief</span><div class=\"typing\"><span></span><span></span><span></span></div>';\n  log.appendChild(typingDiv);\n  log.scrollTop = log.scrollHeight;\n  setThinking(true);\n\n  try{\n    const response = await fetch(CHAT_ENDPOINT, {\n      method: \"POST\",\n      headers: { \"Content-Type\": \"application/json\" },\n      body: JSON.stringify({ messages: messages })\n    });\n    const data = await response.json();\n    if(!response.ok){\n      throw new Error(data && data.error ? data.error : `Server returned ${response.status}`);\n    }\n    const replyText = (data.text || \"\").trim() || \"Hang on, lost my train of thought \u2014 say that again?\";\n    typingDiv.remove();\n    addMessage('bot', replyText);\n    messages.push({role:'assistant', content: replyText});\n  } catch(err){\n    typingDiv.remove();\n    addMessage('bot', \"Well shoot, I'm having some trouble getting connected right now \u2014 nothing you did wrong. Give it a minute and try again.\");\n    console.error(\"Chat request failed:\", err); // full details stay in the browser console, never shown to the customer\n  } finally {\n    setThinking(false);\n    sendBtn.disabled = false;\n    input.focus();\n  }\n}\n\nsendBtn.addEventListener('click', sendMessage);\ninput.addEventListener('keydown', (e)=>{\n  if(e.key === 'Enter' && !e.shiftKey){\n    e.preventDefault();\n    sendMessage();\n  }\n});\ninput.addEventListener('input', ()=>{\n  input.style.height = 'auto';\n  input.style.height = Math.min(input.scrollHeight, 120) + 'px';\n});\n\n// Widget open/close \u2014 greeting fires the first time it's opened, not on page load\nconst chatWidget = document.getElementById('chatWidget');\nconst chatToggle = document.getElementById('chatToggle');\nconst chatPanelClose = document.getElementById('chatPanelClose');\nconst chatBackdrop = document.getElementById('chatBackdrop');\nlet hasGreeted = false;\n\n// ==================== Mode management (landing screen / text / voice) ====================\n// Three mutually-exclusive modes now instead of a simple voice/text boolean \u2014\n// see the .app[data-mode=\"...\"] CSS rules. Persists across closing/reopening\n// the widget within the same page load, so someone who already started a\n// conversation doesn't get bounced back to square one just for closing the\n// panel to look at something else.\nlet currentMode = 'select';\nfunction setMode(mode){\n  currentMode = mode;\n  appEl.dataset.mode = mode;\n}\n\nfunction renderModeSelectChips(){\n  const container = document.getElementById('modeSelectChips');\n  container.innerHTML = '';\n  STARTERS.forEach(q=>{\n    const c = document.createElement('div');\n    c.className = 'chip';\n    c.textContent = q;\n    c.onclick = ()=>{\n      // Tapping a question answers it right away \u2014 no extra step. Talk/Type\n      // buttons below are still there for someone who wants to ask their\n      // own thing instead of picking one of these.\n      hasGreeted = true;\n      setMode('text');\n      input.value = q;\n      sendMessage();\n    };\n    container.appendChild(c);\n  });\n}\nrenderModeSelectChips();\n\ndocument.getElementById('modeChooseTextBtn').addEventListener('click', ()=>{\n  setMode('text');\n  if(!hasGreeted){\n    hasGreeted = true;\n    addMessage('bot', \"Well hey there, I'm Daryl, rucRak's Crew Chief. Tell me what you're wrestlin' with \u2014 install, fitment, or somethin's rattlin' around back there \u2014 and let me know which model you've got: GRUNT or GUNNY. What's goin' on?\");\n  }\n});\n\ndocument.getElementById('modeChooseVoiceBtn').addEventListener('click', ()=>{\n  startVoiceMode(); // this itself calls setMode('voice')\n});\n\nfunction openChat(){\n  chatWidget.classList.add('open');\n  chatBackdrop.classList.add('show');\n  setMode(currentMode); // show whichever mode they were last in (or the landing screen, first time)\n}\nfunction closeChat(){\n  chatWidget.classList.remove('open');\n  chatBackdrop.classList.remove('show');\n  // Don't leave a call running in the background after the panel's closed.\n  if(voiceCallActive && vapiInstance){\n    vapiInstance.stop();\n  }\n  // currentMode is intentionally left as-is \u2014 reopening should return to\n  // wherever they were, not force them back to the landing screen.\n}\nchatToggle.addEventListener('click', openChat);\nchatPanelClose.addEventListener('click', closeChat);\nchatBackdrop.addEventListener('click', closeChat); // clicking outside the panel closes it, like a normal modal\n\n// ==================== VOICE MODE (Vapi) ====================\nconst VAPI_PUBLIC_KEY = \"df87c007-25eb-4771-92c6-8a6a55cdb46c\";\nconst CREW_CHIEF_ASSISTANT_ID = \"d890cde2-65a3-42e5-9832-e9697a3c5775\"; // model, voice, and the full system prompt all live here now \u2014 edit in the Vapi dashboard, not in this file\nconst GREETING_TEXT = \"Well hey there, I'm Daryl, rucRak's Crew Chief. Tell me what you're wrestlin' with \u2014 install, fitment, or somethin's rattlin' around back there \u2014 and let me know which model you've got: GRUNT or GUNNY. What's goin' on?\";\nconst appEl = document.querySelector('.app');\nconst talkBtn = document.getElementById('talkBtn');\nconst voiceStatus = document.getElementById('voiceStatus');\nconst voiceOrb = document.getElementById('voiceOrb');\nconst voiceStartBtn = document.getElementById('voiceStartBtn');\nconst voiceActiveActions = document.getElementById('voiceActiveActions');\nconst voiceSub = document.getElementById('voiceSub');\nconst voiceEndBtn = document.getElementById('voiceEndBtn');\nconst voiceBackTextBtn = document.getElementById('voiceBackTextBtn');\n\nfunction resetVoiceIdleUI(){\n  voiceStatus.textContent = 'Ready when you are';\n  voiceOrb.className = 'voice-orb idle';\n  voiceSub.textContent = 'Crew Chief will start talking as soon as you tap in.';\n  voiceStartBtn.style.display = '';\n  voiceActiveActions.style.display = 'none';\n}\nresetVoiceIdleUI();\n\nlet vapiInstance = null;\nlet voiceCallActive = false;\n\n// Builds a plain-text summary of whatever's already been discussed in text\n// mode, so switching to voice doesn't start from a blank slate. Skips raw\n// image data (can't usefully summarize a photo we don't have a description\n// for) but notes that one was shared, for context.\nfunction buildTextHistorySummary(){\n  if(!messages || messages.length === 0) return null;\n  const lines = [];\n  for(const m of messages){\n    const role = m.role === 'user' ? 'Customer' : 'Daryl';\n    if(typeof m.content === 'string'){\n      lines.push(`${role}: ${m.content}`);\n    } else if(Array.isArray(m.content)){\n      const textParts = m.content.filter(b => b.type === 'text').map(b => b.text);\n      const hadImage = m.content.some(b => b.type === 'image');\n      let line = `${role}: ${textParts.join(' ')}`;\n      if(hadImage) line += ' [customer also shared a fitment photo here]';\n      lines.push(line);\n    }\n  }\n  if(lines.length === 0) return null;\n  return lines.join('\\n');\n}\n\n// Accumulates voice-call turns as they're transcribed, so switching back to\n// text mode (or ending the call) can hand that conversation over to text\n// mode's history \u2014 the reverse direction of the text-to-voice handoff below.\nlet voiceTranscriptBuffer = [];\n\nfunction flushVoiceTranscriptToText(){\n  if(voiceTranscriptBuffer.length === 0) return;\n  for(const turn of voiceTranscriptBuffer){\n    addMessage(turn.role === 'user' ? 'user' : 'bot', turn.text);\n    messages.push({ role: turn.role === 'user' ? 'user' : 'assistant', content: turn.text });\n  }\n  voiceTranscriptBuffer = [];\n  hasGreeted = true; // don't re-fire the canned text greeting after a real voice conversation happened\n}\n\n// Shared, defensive wrapper for injecting a message into a live call \u2014\n// tries vapi.send() first (the documented method), falls back to\n// vapi.addMessage() if that doesn't exist (an alternate method name seen in\n// some Vapi docs), and logs clearly which path was taken or whether both\n// failed, since a silent failure here is otherwise impossible to diagnose.\n// Only used for genuinely mid-call events now (like a photo analysis result)\n// \u2014 the initial text-to-voice handoff goes through variableValues at call\n// start instead (see startVoiceMode), which is more reliable since it\n// doesn't race against the assistant's own opening greeting.\nfunction sendVapiMessage(vapi, message, label){\n  try {\n    if(typeof vapi.send === 'function'){\n      console.log(`Sending ${label} via vapi.send()...`);\n      vapi.send({ type: 'add-message', message });\n      console.log(`vapi.send() for ${label} completed without throwing.`);\n    } else if(typeof vapi.addMessage === 'function'){\n      console.log(`vapi.send is not a function on this instance \u2014 trying vapi.addMessage() for ${label}...`);\n      vapi.addMessage(message);\n      console.log(`vapi.addMessage() for ${label} completed without throwing.`);\n    } else {\n      console.error(`Neither vapi.send nor vapi.addMessage exist on this instance \u2014 ${label} cannot be delivered.`);\n    }\n  } catch(err){\n    console.error(`${label} threw an error:`, err);\n  }\n}\n\n// Vapi error objects can take several different shapes depending on what\n// actually went wrong (a plain string, an Error, {message: \"...\"},\n// {message: {...nested...}}, {error: {message: \"...\"}}, or something else\n// entirely) \u2014 blindly concatenating err.message produces \"[object Object]\"\n// whenever message itself isn't a plain string. This unpacks it properly so\n// the on-screen error text is actually useful instead of that.\nfunction describeVapiError(err){\n  if(!err) return 'unknown error';\n  if(typeof err === 'string') return err;\n  if(typeof err.message === 'string') return err.message;\n  if(err.message && typeof err.message === 'object'){\n    try { return JSON.stringify(err.message); } catch(e){ /* fall through */ }\n  }\n  if(err.error && typeof err.error.message === 'string') return err.error.message;\n  if(err.error && typeof err.error === 'string') return err.error;\n  try { return JSON.stringify(err); } catch(e){ return String(err); }\n}\n\nfunction attachVapiListeners(vapi){\n  vapi.on('call-start', ()=>{\n    voiceCallActive = true;\n    voiceStatus.textContent = 'Connected';\n    voiceOrb.className = 'voice-orb listening';\n    voiceSub.textContent = \"Say what's going on \u2014 Crew Chief's listening.\";\n    voiceStartBtn.style.display = 'none';\n    voiceActiveActions.style.display = 'flex';\n    voiceTranscriptBuffer = []; // fresh call, don't carry over anything stale\n\n    // If someone tapped \"Send a photo\" before starting the call, this lets\n    // that flow continue now that we're actually connected.\n    pendingCallStartResolvers.forEach(resolve => resolve());\n    pendingCallStartResolvers = [];\n  });\n\n  vapi.on('call-end', ()=>{\n    voiceCallActive = false;\n    flushVoiceTranscriptToText(); // hand the voice conversation over to text mode's history\n    // Back to the idle \"tap to start\" screen, not text \u2014 they can still choose to switch manually.\n    resetVoiceIdleUI();\n  });\n\n  vapi.on('speech-start', ()=>{\n    voiceStatus.textContent = 'Crew Chief is talking...';\n    voiceOrb.className = 'voice-orb speaking';\n  });\n\n  vapi.on('speech-end', ()=>{\n    voiceStatus.textContent = 'Listening...';\n    voiceOrb.className = 'voice-orb listening';\n  });\n\n  // Captures the live transcript so it can be handed to text mode later \u2014\n  // see flushVoiceTranscriptToText above. Requires \"transcript\" to be\n  // enabled in the assistant's clientMessages in the Vapi dashboard; if\n  // it's not receiving these, double-check that setting there.\n  vapi.on('message', (message)=>{\n    if(message && message.type === 'transcript' && message.transcriptType === 'final' && message.transcript){\n      voiceTranscriptBuffer.push({ role: message.role === 'user' ? 'user' : 'assistant', text: message.transcript });\n    }\n  });\n\n  vapi.on('error', (err)=>{\n    console.error('Vapi error:', err);\n    voiceStatus.textContent = \"Couldn't connect\";\n    voiceSub.textContent = 'Error: ' + describeVapiError(err);\n    voiceOrb.className = 'voice-orb';\n    voiceStartBtn.style.display = '';\n    voiceActiveActions.style.display = 'none';\n  });\n}\n\n// Vapi's raw @vapi-ai/web UMD build doesn't reliably expose window.Vapi when loaded via a\n// plain CDN script tag (confirmed dead end). This is Vapi's own officially-documented loader\n// for exactly this vanilla-JS/no-bundler scenario instead \u2014 loads async, calls vapiSDK.run()\n// on completion, and returns an instance with the same on()/start()/stop() API. We hide its\n// default floating button via the .vapi-btn CSS rule since we have our own custom UI.\nconst vapiReadyPromise = new Promise((resolve, reject)=>{\n  const script = document.createElement('script');\n  script.src = \"https://cdn.jsdelivr.net/gh/VapiAI/html-script-tag@latest/dist/assets/index.js\";\n  script.defer = true;\n  script.async = true;\n  script.onload = function(){\n    try {\n      if(!window.vapiSDK){\n        reject(new Error('Vapi loader script loaded but window.vapiSDK is missing.'));\n        return;\n      }\n      const vapi = window.vapiSDK.run({\n        apiKey: VAPI_PUBLIC_KEY,\n        assistant: CREW_CHIEF_ASSISTANT_ID,\n        config: {} // default button hidden via CSS \u2014 we drive everything through our own UI\n      });\n      if(!vapi){\n        reject(new Error('vapiSDK.run() did not return an instance.'));\n        return;\n      }\n      attachVapiListeners(vapi);\n      vapiInstance = vapi;\n      resolve(vapi);\n    } catch(err){\n      reject(err);\n    }\n  };\n  script.onerror = function(){\n    reject(new Error('Vapi loader script failed to load from CDN \u2014 check network/ad-blockers.'));\n  };\n  const firstScript = document.getElementsByTagName('script')[0];\n  firstScript.parentNode.insertBefore(script, firstScript);\n});\n\n// Set right before calling startVoiceMode() when there's a specific topic to\n// hand off (e.g. a chip picked from the landing screen). Falls back to the\n// prior text conversation if this isn't explicitly set.\nlet voiceStartContext = null;\n\nfunction startVoiceMode(){\n  setMode('voice');\n  voiceStatus.textContent = 'Connecting...';\n  voiceOrb.className = 'voice-orb';\n  voiceSub.textContent = 'Hang on, getting Crew Chief on the line.';\n  voiceStartBtn.style.display = 'none'; // prevent double-tapping while it connects\n\n  // Context handed to the assistant via variableValues, set BEFORE the call\n  // starts rather than injected mid-call \u2014 this sidesteps an entire class of\n  // timing/interruption problems that come with sending a message while the\n  // assistant might already be speaking. Requires the Vapi dashboard's\n  // system prompt to reference {{priorContext}} and the First Message field\n  // to have a conditional greeting based on it (see README/setup notes).\n  const contextForCall = voiceStartContext || buildTextHistorySummary() || \"\";\n  voiceStartContext = null; // one-shot, don't leak into the next call\n\n  vapiReadyPromise\n    .then((vapi)=>{\n      // Assistant (model, voice, and the full system prompt) is managed entirely in the\n      // Vapi dashboard now \u2014 one single source of truth, no duplicated prompt to drift\n      // out of sync with. Edit the assistant there, not here.\n      // vapiSDK.run() above only sets up the instance \u2014 it doesn't start a call on its own,\n      // so we always explicitly start one here in response to the tap.\n      if(!voiceCallActive){\n        const startResult = vapi.start(CREW_CHIEF_ASSISTANT_ID, {\n          variableValues: { priorContext: contextForCall }\n        });\n        if(startResult && typeof startResult.catch === 'function'){\n          startResult.catch((err)=>{\n            console.error('Vapi start() rejected:', err);\n            voiceStatus.textContent = \"Couldn't connect\";\n            voiceSub.textContent = 'Error: ' + describeVapiError(err);\n            voiceOrb.className = 'voice-orb';\n            voiceStartBtn.style.display = '';\n          });\n        }\n      }\n    })\n    .catch((err)=>{\n      console.error('Voice mode failed to start:', err);\n      voiceStatus.textContent = \"Couldn't connect\";\n      voiceSub.textContent = 'Error: ' + describeVapiError(err);\n      voiceOrb.className = 'voice-orb';\n      voiceStartBtn.style.display = '';\n    });\n}\n\nfunction endVoiceMode(){\n  // Stops the call and returns to the voice screen's idle \"tap to start\"\n  // state \u2014 stays in voice mode. Use switchToTextMode() to actually leave\n  // voice mode for text.\n  if(voiceCallActive && vapiInstance){\n    vapiInstance.stop();\n  }\n  resetVoiceIdleUI();\n}\n\nfunction switchToTextMode(){\n  if(voiceCallActive && vapiInstance){\n    vapiInstance.stop(); // call-end handler flushes the transcript into text mode's history\n  }\n  resetVoiceIdleUI();\n  setMode('text');\n}\n\nvoiceStartBtn.addEventListener('click', startVoiceMode);\ntalkBtn.addEventListener('click', startVoiceMode);\nvoiceEndBtn.addEventListener('click', endVoiceMode);\nvoiceBackTextBtn.addEventListener('click', switchToTextMode);\n";
  document.body.appendChild(widgetScript);
})();
